import { test } from 'node:test';
import assert from 'node:assert/strict';
import { collect } from '../src/collect.js';

test('returns exactly target items when source has enough on first call', async () => {
  const source = async () => ['a', 'b', 'c', 'd', 'e'];
  const result = await collect(3, source);
  assert.deepEqual(result, ['a', 'b', 'c']);
