test('deduplicates across rounds and keeps calling until target is reached', async () => {
  let call = 0;
  const source = async () => {
    call++;
    if (call === 1) return ['a', 'b'];
    if (call === 2) return ['b', 'c']; // 'b' is a duplicate
    return ['d'];
