test('logs new-item count each round to console.log', async () => {
  const logs = [];
  const originalLog = console.log;
  console.log = (...args) => logs.push(args.join(' '));

  let call = 0;
  const source = async () => {
    call++;
    if (call === 1) return ['x', 'y'];
    return ['z'];
  };

  try {
    await collect(3, source);
  } finally {
    console.log = originalLog;
  }

  assert.equal(logs.length, 2);
  assert.match(logs[0], /\+2/);   // round 1: 2 new items
  assert.match(logs[1], /\+1/);   // round 2: 1 new item
