- [ ] **Step 3: Create `src/collect.js` with minimal implementation**

```js
export async function collect(target, findCandidates) {
  const seen = new Set();
  let round = 0;

  while (seen.size < target) {
    round++;
    const before = seen.size;
    const candidates = await findCandidates();
    for (const item of candidates) {
      seen.add(item);
    }
    const added = seen.size - before;
    console.log(`Round ${round}: +${added} new (total ${seen.size}/${target})`);
  }

  return [...seen].slice(0, target);
}
```

